/* VOYAGE | Approved Scene10 pair restore, 2026-11-26.
 * Narrow scope: two cards before the eleven unchanged quick links.
 * Reuses ORIGINAL approved illustrations (not regenerated). No seed trip/packing writes.
 */
(()=>{'use strict';
const AIRPORT="data:image/webp;base64,";
const PALACE="data:image/webp;base64,";
const U=window.VoyageUI;
const home=document.getElementById('v2Home');
if(!U||!home)return;
if(!document.getElementById('voyage-scene10-cards-style')){
 const style=document.createElement('style');
 style.id='voyage-scene10-cards-style';
 style.textContent="\n/* Reinstated from approved Scene10. Scoped: never restyle existing quick links. */\n#v2Home .voyage-story-pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-items:stretch;gap:14px;margin:14px 0 20px;position:relative}\n#v2Home .voyage-story-card{position:relative;display:block;box-sizing:border-box;width:100%;min-width:0;height:232px;min-height:232px;overflow:hidden;border:2.4px solid #232743;border-radius:28px;background:#ffe7e5;color:#263146;padding:12px 14px;text-align:left;font:inherit;box-shadow:none;isolation:isolate}\n#v2Home button.voyage-story-card{cursor:pointer}\n#v2Home .voyage-story-card.voyage-story-reminder{background:#fff1d2}\n#v2Home .voyage-story-head{display:flex;align-items:center;gap:9px;min-height:37px;position:relative;z-index:4;font-weight:800;font-size:17px;line-height:1.15;color:#263146}\n#v2Home .voyage-story-head .voyage-story-icon{width:32px;height:32px;flex:none;display:block}\n#v2Home .voyage-story-head svg{display:block;width:100%;height:100%}\n#v2Home .voyage-story-next .voyage-story-head .voyage-story-arrow{margin-left:auto;font-size:24px;font-weight:700}\n#v2Home .voyage-story-reminder .voyage-story-head{background:transparent;border:0;padding:0;width:100%;font:inherit;font-weight:800;font-size:17px;text-align:left;cursor:pointer}\n#v2Home .voyage-story-reminder .voyage-story-arrow{margin-left:auto;font-size:24px;font-weight:700}\n#v2Home .voyage-story-ticket{position:relative;z-index:3;display:grid;grid-template-columns:62px minmax(0,1fr);align-items:stretch;gap:10px;min-height:66px;margin-top:9px;padding:8px 10px;border-radius:17px;background:#fff9f9ed;color:#33435c}\n#v2Home .voyage-story-date{display:flex;flex-direction:column;justify-content:center;align-items:center;gap:1px;border-right:1px solid #e3d6db;padding-right:7px;text-align:center}\n#v2Home .voyage-story-date b{font-size:17px;line-height:1.2}\n#v2Home .voyage-story-date small{font-size:11px}\n#v2Home .voyage-story-flight-info{min-width:0;display:flex;flex-direction:column;justify-content:center;gap:5px}\n#v2Home .voyage-story-flight-info strong{font-size:15px;line-height:1.25;overflow-wrap:anywhere}\n#v2Home .voyage-story-flight-info small{font-size:12px;color:#58627a;line-height:1.35;overflow-wrap:anywhere}\n#v2Home .voyage-story-checklist{display:grid;gap:8px;position:relative;z-index:3;margin-top:14px}\n#v2Home .voyage-story-checklist label{display:flex;align-items:flex-start;gap:9px;font-size:13px;line-height:1.28;font-weight:650;color:#2d3a50;cursor:pointer;min-width:0}\n#v2Home .voyage-story-checklist input{display:block;flex:0 0 21px;width:21px;height:21px;margin:0;accent-color:#89b99a;cursor:pointer}\n#v2Home .voyage-story-checklist span{min-width:0;overflow-wrap:anywhere}\n#v2Home .voyage-story-checklist .voyage-story-empty{font-weight:500;font-size:12px}\n#v2Home .voyage-story-art{position:absolute;left:0;right:0;bottom:-1px;height:84px;z-index:1;pointer-events:none;overflow:hidden}\n#v2Home .voyage-story-art img{display:block;width:100%;height:100%;object-fit:fill;user-select:none}\n#v2Home .voyage-story-next:focus-visible,#v2Home .voyage-story-reminder .voyage-story-head:focus-visible,#v2Home .voyage-story-checklist input:focus-visible{outline:3px solid #3769c0;outline-offset:2px}\n#v2Home .voyage-story-card .voyage-story-ticket,#v2Home .voyage-story-card .voyage-story-checklist{margin-bottom:80px}\n@media(max-width:850px){\n#v2Home .voyage-story-pair{grid-template-columns:minmax(0,1fr);gap:13px;max-width:520px;margin:12px 0 20px}\n#v2Home .voyage-story-card{height:226px;min-height:226px;padding:13px 15px}\n#v2Home .voyage-story-head{font-size:17px}\n#v2Home .voyage-story-reminder .voyage-story-head{font-size:17px}\n#v2Home .voyage-story-checklist{gap:7px}\n}\n@media(max-width:390px){\n#v2Home .voyage-story-card{height:223px;min-height:223px;padding:11px}\n#v2Home .voyage-story-ticket{grid-template-columns:52px minmax(0,1fr);gap:7px;padding:7px 8px}\n#v2Home .voyage-story-flight-info strong{font-size:13px}\n#v2Home .voyage-story-checklist label{font-size:12px}\n#v2Home .voyage-story-art{height:77px}\n}\n";
 document.head.append(style);
}
function el(tag,cls,text){
 const x=document.createElement(tag);
 if(cls)x.className=cls;
 if(text!==undefined)x.textContent=String(text);
 return x;
}
const planeSVG='<svg viewBox="0 0 26 26" aria-hidden="true"><circle cx="13" cy="13" r="11.2" fill="#F2B6B8" stroke="#314158" stroke-width="1.7"/><path d="M5 15L20 6L15 21L11 15L5 15Z" fill="#FFF9EA" stroke="#314158" stroke-width="1.7" stroke-linejoin="round"/></svg>';
const bellSVG='<svg viewBox="0 0 26 26" aria-hidden="true"><path d="M5 19h16l-3-4V10a5 5 0 0 0-10 0v5Z" fill="#FFE98B" stroke="#314158" stroke-width="1.8" stroke-linejoin="round"/><path d="M11 21q2 4 4 0" fill="none" stroke="#314158" stroke-width="1.8" stroke-linecap="round"/></svg>';
function create(){
 const pair=el('div','voyage-story-pair');
 pair.id='voyage-approved-scene10-cards';
 const next=el('button','voyage-story-card voyage-story-next');next.type='button';
 next.setAttribute('aria-label','開啟下一個行程');
 next.innerHTML='<span class="voyage-story-head"><span class="voyage-story-icon">'+planeSVG+'</span><span>下一個行程</span><span class="voyage-story-arrow">›</span></span><span class="voyage-story-ticket"><span class="voyage-story-date"><b data-story-date>—</b><small data-story-weekday></small></span><span class="voyage-story-flight-info"><strong data-story-trip>尚未安排航班</strong><small data-story-flight-detail>點我查看行程</small></span></span>';
 next.addEventListener('click',()=>document.querySelector('[data-tablink="itinerary"]')?.click());
 const reminder=el('section','voyage-story-card voyage-story-reminder');
 const head=el('button','voyage-story-head');head.type='button';head.setAttribute('aria-label','前往行李清單管理旅行提醒');
 head.innerHTML='<span class="voyage-story-icon">'+bellSVG+'</span><span>旅行小提醒</span><span class="voyage-story-arrow">›</span>';
 head.addEventListener('click',showAllReminders);
 reminder.append(head,el('div','voyage-story-checklist'));
 for(const [card,url] of [[next,AIRPORT],[reminder,PALACE]]){
  const art=el('span','voyage-story-art'),img=el('img');
  img.alt='';img.loading='eager';img.decoding='async';img.draggable=false;img.src=url;art.append(img);card.append(art);
 }
 pair.append(next,reminder);return pair;
}
function isKorea(t){return /韓國|Korea|Seoul|首爾|서울/i.test([t.country,t.city].join(' '));}
function isSeoul(t){return window.VoyageRegionV4?.countryCode?.(t)==='KR'&&!window.VoyageHomeGuard?.cityMismatch?.(t)&&/首爾|Seoul|서울/i.test(String(t.city||''));}
function validDate(s){return /^\d{4}-\d{2}-\d{2}$/.test(String(s||''));}
function dateAfter(start,offset){
 if(!validDate(start))return '';
 const at=new Date(start+'T12:00:00Z');at.setUTCDate(at.getUTCDate()+offset);
 return at.toISOString().slice(0,10);
}
function today(t){
 const region=isKorea(t)?'Asia/Seoul':String(t.tz||'Asia/Taipei');
 try{
  const fields=new Intl.DateTimeFormat('en-CA',{timeZone:region,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
  const out=Object.fromEntries(fields.filter(f=>f.type!=='literal').map(f=>[f.type,f.value]));
  return out.year+'-'+out.month+'-'+out.day;
 }catch(e){return new Date().toISOString().slice(0,10);}
}
function nextItem(t){
 const currentDate=today(t);
 const upcoming=[];
 for(const doc of Array.isArray(t.documents)?t.documents:[]){
  if(doc?.type!=='flight')continue;
  const date=validDate(doc.date)?doc.date:'';
  if(date && date<currentDate)continue;
  upcoming.push({date,kind:'flight',time:doc.time||'',title:doc.name||'航班資料已建立',place:doc.place||'',notes:doc.note||''});
 }
 for(let day=0;day<(t.days||[]).length;day++){
  const date=dateAfter(t.startDate,day);
  if(!date||date<currentDate)continue;
  for(const item of Array.isArray(t.days[day])?t.days[day]:[]){
   if(!item||!String(item.name||'').trim())continue;
   upcoming.push({date,kind:'event',time:item.time||'',title:item.name,notes:''});
  }
 }
 upcoming.sort((a,b)=>String(a.date||'9999').localeCompare(String(b.date||'9999'))||String(a.time||'00:00').localeCompare(String(b.time||'00:00'))||(a.kind==='flight'?-1:1));
 if(upcoming.length)return upcoming[0];
 return validDate(t.startDate)&&t.startDate>=currentDate?{date:t.startDate,kind:'trip',title:t.city||'旅行已建立',time:''}:null;
}

/* Purpose-built country checklist; no dependency on packing or automatic verification. */
const COUNTRY_RULES={
 KR:{name:'韓國',items:[
 ['passport','檢查護照效期及韓國入境資格','https://www.visa.go.kr/'],
 ['keta','確認 K-ETA 豁免或申請適用性（依護照與日期）','https://www.k-eta.go.kr/'],
 ['arrival','確認韓國 e-Arrival 入境申報是否適用','https://www.e-arrivalcard.go.kr/'],
 ['tmoney','準備 T-money 交通卡與機場接駁',''],
 ['network','準備韓國 eSIM、網路和地圖','']]},
 JP:{name:'日本',items:[
 ['passport','檢查護照效期及日本免簽／簽證資格','https://www.mofa.go.jp/j_info/visit/visa/short/novisa.html'],
 ['visitjapan','確認 Visit Japan Web 入境、海關填寫方式','https://services.digital.go.jp/en/visit-japan-web/'],
 ['transit','準備 Suica／PASMO 或當地車票',''],
 ['booking','核對住宿、航班與機場交通',''],
 ['network','準備日本上網及付款方式','']]},
 TH:{name:'泰國',items:[
 ['passport','確認護照效期及泰國簽證／免簽資格','https://www.thaievisa.go.th/'],
 ['tdac','於抵達前 3 天內確認及辦理 TDAC 入境卡','https://tdac.immigration.go.th/'],
 ['transit','確認 BTS／MRT 車票及機場交通',''],
 ['network','準備泰國 eSIM 及叫車方式',''],
 ['money','準備泰銖及付款方式','']]},
 VN:{name:'越南',items:[
 ['passport','確認護照效期與越南簽證／免簽資格','https://evisa.gov.vn/'],
 ['evisa','若需要 e-Visa，確認核發及有效日期','https://evisa.gov.vn/'],
 ['hotel','核對住宿地址、機票及入境資料',''],
 ['transit','準備機場接送與市區交通',''],
 ['money','準備越南網路、越盾及付款方式','']]},
 OTHER:{name:'目的地',items:[
 ['passport','確認護照效期及入境資格',''],
 ['arrival','確認入境申報及海關最新規定',''],
 ['transit','確認機場與當地交通方式',''],
 ['hotel','核對住宿、航班及訂單',''],
 ['network','準備上網及當地付款方式','']]}
};
function countryCode(t){
 const s=String(t?.country||'')+' '+String(t?.city||'');
 if(/韓國|南韓|korea|대한민국|seoul|首爾|서울/i.test(s))return'KR';
 if(/日本|japan|tokyo|osaka|東京|大阪/i.test(s))return'JP';
 if(/泰國|thailand|bangkok|曼谷|ไทย/i.test(s))return'TH';
 if(/越南|vietnam|viet nam|hanoi|saigon|河內|胡志明/i.test(s))return'VN';
 return'OTHER';
}
function countryInfo(t){
 const code=countryCode(t),data=COUNTRY_RULES[code];
 return {code,name:data.name,items:data.items.map(([id,label,url])=>({id,label,url}))};
}
function doneStates(t,code){
 const v=t?.countryReminderChecks?.[code];
 return v&&typeof v==='object'&&!Array.isArray(v)?v:{};
}
function saveDone(id,done){
 const t=U.current?.();if(!t||typeof U.save!=='function')return;
 const code=countryCode(t);
 if(!COUNTRY_RULES[code].items.some(x=>x[0]===id))return;
 if(!t.countryReminderChecks||typeof t.countryReminderChecks!=='object')t.countryReminderChecks={};
 if(!t.countryReminderChecks[code]||typeof t.countryReminderChecks[code]!=='object')t.countryReminderChecks[code]={};
 t.countryReminderChecks[code][id]=!!done;
 U.save();render();
}
const modalStyle=el('style');
modalStyle.textContent='dialog.voyage-country-tasks{box-sizing:border-box;width:min(90vw,580px);max-height:82dvh;overflow:auto;padding:20px;border:2px solid #253148;border-radius:20px;background:#fffefa;color:#253148}dialog.voyage-country-tasks::backdrop{background:#17284688}.voyage-country-tasks h2{font-size:19px;margin:0 0 12px}.voyage-country-tasks p{font-size:12px;line-height:1.5;color:#5c6373}.voyage-country-tasks label{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid #e6e3dd;font-size:14px}.voyage-country-tasks label span{flex:1}.voyage-country-tasks input{width:20px;height:20px;flex:none;accent-color:#8cb89c}.voyage-country-tasks a{font-size:12px;color:#385ab9}.voyage-country-tasks button{margin-top:16px;padding:11px;border-radius:12px;width:100%;background:#edf1ff;border:1px solid #b1b8ca;font-weight:750}';
document.head.append(modalStyle);
function showAllReminders(){
 const t=U.current?.();if(!t)return;
 const r=countryInfo(t),dlg=el('dialog','voyage-country-tasks'),heading=el('h2','',r.name+' · 旅行小提醒');
 const count=el('p'),summary=()=>{
  const state=doneStates(U.current?.(),r.code);
  count.textContent='已自行確認 '+r.items.filter(x=>state[x.id]).length+'／'+r.items.length+' 項。勾選不代表系統已審核護照、簽證或入境申報。';
 };
 summary();
 dlg.append(heading,count,el('p','','以下依目的地國家提供出發前提醒；實際規定依護照國籍、入境日期及旅行目的不同，請透過官方連結重新查核。'));
 for(const item of r.items){
  const line=el('label'),input=el('input'),txt=el('span','',item.label);
  input.type='checkbox';input.checked=!!doneStates(t,r.code)[item.id];
  input.addEventListener('change',()=>{saveDone(item.id,input.checked);summary();});
  line.append(input,txt);
  if(item.url){const link=el('a','','官方查核');link.href=item.url;link.target='_blank';link.rel='noopener noreferrer';link.addEventListener('click',e=>e.stopPropagation());line.append(link);}
  dlg.append(line);
 }
 const exit=el('button','','返回旅行首頁');exit.type='button';exit.addEventListener('click',()=>dlg.close());
 dlg.append(exit);dlg.addEventListener('close',()=>dlg.remove(),{once:true});
 document.body.append(dlg);dlg.showModal();
}
function render(){
 const t=U.current?.();if(!t)return;
 let pair=home.querySelector('#voyage-approved-scene10-cards');
 const quick=[...home.querySelectorAll(':scope > .v2-section-label')].find(x=>x.textContent.includes('旅行快速入口'));
 if(!quick)return;
 if(!pair){pair=create();home.insertBefore(pair,quick);}
 else if(pair.nextElementSibling!==quick)home.insertBefore(pair,quick);
 pair.querySelectorAll('.voyage-story-art').forEach(node=>{node.hidden=!isSeoul(t);});
 const next=window.VoyageHomeGuard?.cityMismatch?.(t)?null:nextItem(t),date=next?.date||'';
 pair.querySelector('[data-story-date]').textContent=date?date.slice(5).replace('-','/'):'—';
 pair.querySelector('[data-story-weekday]').textContent=date?'（'+['日','一','二','三','四','五','六'][new Date(date+'T12:00:00Z').getUTCDay()]+'）':'';
 pair.querySelector('[data-story-trip]').textContent=next?.title||'尚無下一個行程';
 const detail=pair.querySelector('[data-story-flight-detail]');
 if(next?.kind==='flight')detail.textContent=[next.time&&next.time+' 起飛',next.place&&'航班／機場：'+next.place].filter(Boolean).join(' · ')||'航班時間待設定';
 else if(next?.kind==='event')detail.textContent=next.time?next.time+' · 已排入旅程':'已排入旅程 · 時間待設定';
 else detail.textContent=next?'尚未新增航班，點此編排行程':'點此新增旅行或行程';
 const list=pair.querySelector('.voyage-story-checklist');list.replaceChildren();
 const cfg=countryInfo(t),status=doneStates(t,cfg.code);
 const items=cfg.items.slice(0,3);
 pair.querySelector('.voyage-story-reminder .voyage-story-head').title=cfg.name+' · 已確認 '+cfg.items.filter(x=>status[x.id]).length+'/'+cfg.items.length+'，點此查看所有提醒';
 for(const item of items){
  const line=el('label'),input=el('input'),label=el('span','',item.label);
  input.type='checkbox';input.checked=!!status[item.id];input.setAttribute('aria-label',cfg.name+'：'+item.label);
  input.addEventListener('change',()=>saveDone(item.id,input.checked));
  line.append(input,label);list.append(line);
 }
}
let scheduled=false;
function update(){if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;render();});}
new MutationObserver(update).observe(home,{childList:true});
update();

})();